const input = $input.first().json;
const category = String(input.business_category || 'General').toLowerCase();
const topic = String(input.query_topic || '').toLowerCase();

let advice = "";

if (category.includes('tech') || category.includes('electronics') || category.includes('hardware')) {
  advice = "Global shipping lanes and component manufacturing hubs are facing minor logistics adjustments. For tech importers in Nasser Road/Kampala, component acquisition costs are projected to trend upward. Recommendation: Secure current wholesale stock levels for fast-moving items (chargers, protectors, cables) to protect profit margins before restocking prices shift.";
} else if (category.includes('fashion') || category.includes('boutique') || category.includes('wear')) {
  advice = "Cross-border transport and textile supply costs are stabilizing, but seasonal demand spikes are approaching. Recommendation: Lock in regional apparel orders early and focus marketing on unique urban styles to capture high-margin retail traffic.";
} else {
  advice = "Regional currency shifts (USD/UGX) and fuel price adjustments are impacting transport overheads. Recommendation: Optimize local delivery batching and maintain 14-day buffer stock on high-demand inventory.";
}

return [{
  json: {
    status: "success",
    market_advisory: advice,
    action_tier: "PROACTIVE_PROTECTION",
    timestamp: new Date().toISOString()
  }
}];
